mapper.sql:
where 1=1

		and cpvd_llave = #{llaveTabla}


		and cpvd_estado = #{estado}


		and cpvd_origen = #{origen}


		and cpvd_origencategoria = #{origenCategoria}


		and cpvd_codigo = #{codigo}


		and cpvd_nombre = #{nombre}


		and cpvd_grupo = #{grupo}


		and bpvd_textoculto = #{textOcultoFilter}


		and bpvd_necesitadesarrollo = #{necesitaDesarrolloFilter}


		and bpvd_incluirpreloadorigen = #{incluirPreloadOrigenFilter}


		and bpvd_multiple = #{multipleFilter}


		and bpvd_piderol = #{pideRolFilter}


		and bpvd_pidetiempobloqueo = #{pideTiempoBloqueoFilter}


		and bpvd_propiedadboolean = #{propiedadBooleanFilter}


		and bpvd_pideusuario = #{pideUsuarioFilter}


		and bpvd_solicitamotivo = #{solicitaMotivoFilter}


		and bpvd_pidefechas = #{pideFechasFilter}


		and bpvd_privada = #{privadaFilter}


		and (upper(cpvd_nombre) like upper('%' || #{filtroParametro} || '%'))

mapper.select:

where 1=1

		and cpvd_estado = #{estado}


		and cpvd_origen = #{origen}


		and (cpvd_origencategoria = #{origenCategoria} or cpvd_origencategoria is null)


		and cpvd_codigo = #{codigo}


		and cpvd_nombre = #{nombre}


		and cpvd_grupo = #{grupo}


		and (upper(cpvd_nombre) like upper('%' || #{filtroParametro} || '%'))

order by cpvd_origen 
, cpvd_nombre
